package com.codetyper.app;
public class CodeTyperEngine { public static class Result { public boolean success; public String output; public int accuracy,wpm; Result(boolean s,String o,int a,int w){success=s;output=o;accuracy=a;wpm=w;} }
 public static String normalize(String s){return s.replace("\r\n","\n").trim();}
 public static Result run(Lesson l,String typed,long ms){ String a=normalize(typed), b=normalize(l.code_to_type); int total=Math.max(b.length(),1), same=0; for(int i=0;i<Math.min(a.length(),b.length());i++) if(a.charAt(i)==b.charAt(i)) same++; int acc=Math.round(same*100f/total); int words=Math.max(1,a.trim().isEmpty()?0:a.trim().split("\\s+").length); int wpm=(int)Math.round(words/(Math.max(ms,1)/60000.0)); if(a.equals(b)) return new Result(true,l.expected_output,acc,wpm); String err=a.length()<b.length()?"SyntaxError: incomplete code":"SyntaxError: code does not match the lesson"; if(a.contains("print(")&&!a.contains(")")) err="SyntaxError: missing ')'"; else if(a.contains("if ")&&!a.contains(":")) err="SyntaxError: expected ':'"; else if(a.contains("print(")&&!a.contains("\"")) err="SyntaxError: check your quotes"; return new Result(false,err,acc,wpm); }
}
